const i={ui:{fig:"Fig. 1",title:"Cestino di stoffa · anatomia",svgLabel:"Un disegno isometrico del cestino di stoffa foderato e di come si cuce, passo dopo passo.",prev:"Passo precedente",dot:(o,a)=>o?`Passo ${o}: ${a}`:a,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(o,a)=>`Passo ${o} di ${a}`,machine:o=>`Macchina: ${o.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Scomponi",putTogether:"Ricomponi",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE",cutTitle:"Cestino di stoffa · misure di taglio",cutAlt:"Schema di taglio di un cestino di stoffa foderato: l'esterno e la fodera, ciascuno un quadrato di 60 × 60 cm con un quadrato di 20 × 20 cm tagliato via da ogni angolo, e cinque quadrati di teletta di 19 × 19 cm.",cutCaption:"I pezzi da tagliare, con le loro misure, come nel passaggio 1."},stitches:{straight:"Punto dritto"},labels:{cm60:"60 cm",cm20:"20 cm",cm19:"19 cm",cutCorners:"taglia via gli angoli",outerCotton:"esterno · cotone",liningCotton:"fodera · cotone",iface5:"5 × teletta",wrongSideUp:"esterno, rovescio in su",ironOn:"fissa con il ferro",edges05:"a 0,5 cm dai bordi",turnOver:"capovolgilo",rightSideIn:"dritto all'interno",seam05:"cuci a 0,5 cm",toThePoint:"fino alla punta",opening15:"apertura 15 cm",sameAsOuter:"come l'esterno",outerRightOut:"esterno sul dritto",rightSides:"dritto contro dritto",turnThrough:"rivolta dall'apertura",stitchClosed:"chiudi l'apertura",pushLining:"spingi dentro la fodera",topstitch05:"impuntura a 0,5 cm",hotGlue:"colla a caldo, senza cucire",jointFlat:"giunzione su un lato",bows4:"un fiocco su ogni angolo",christmas:"Natale: pizzo + fiocchi",halloween:"Halloween: nastro nero",everyday:"ogni giorno: senza decori"},steps:[{title:"Il cestino finito",text:"Un cestino di stoffa foderato: esterno in cotone irrigidito con la teletta, fodera in cotone, pizzo e fiocchi incollati. Tocca il cestino per scomporlo."},{title:"Taglia i pezzi",text:"Esterno e fodera: un quadrato di cotone di 60 × 60 cm ciascuno, con un quadrato di 20 × 20 cm tagliato via da ogni angolo. Teletta: cinque quadrati di 19 × 19 cm.",details:["Taglia un quadrato di cotone di 60 × 60 cm per l'esterno e un altro uguale per la fodera.","Da ogni angolo di entrambi i quadrati taglia via un quadrato di 20 × 20 cm. Resta una croce: il quadrato al centro è il fondo, i quattro bracci sono le pareti.","Dalla teletta termoadesiva rigida taglia cinque quadrati di 19 × 19 cm: uno per il fondo e uno per ogni parete dell'esterno.","Tutti i margini di cucitura di questo cestino sono di 0,5 cm.","La scritta nel video riporta 50 × 50 cm: è un errore, i quadrati sono di 60 × 60 cm."]},{title:"Applica la teletta",text:"Stendi l'esterno con il rovescio verso l'alto. Metti un quadrato di teletta al centro del fondo e di ogni parete, a 0,5 cm dai bordi, e fissalo con il ferro.",details:["Stendi la croce dell'esterno con il rovescio verso l'alto.","Appoggia un quadrato di teletta, con il lato adesivo verso il basso, al centro del fondo e di ciascuna delle quattro pareti — a 0,5 cm dai bordi tutto intorno, così resta fuori dalle cuciture.","Fissa i quadrati con il ferro da stiro. La teletta va solo sull'esterno, non sulla fodera."]},{title:"Cuci l'esterno",text:"Capovolgi l'esterno con il dritto verso l'alto e solleva le pareti. Appunta i bordi che si incontrano e fai le quattro cuciture d'angolo a 0,5 cm, dall'alto fino alla punta.",details:["Capovolgi la croce dell'esterno, con il dritto verso l'alto.","Solleva le pareti in modo che i bordi di due pareti vicine si incontrino, dritto contro dritto. Fissali con gli spilli.","Fai la cucitura d'angolo a 0,5 cm dal bordo, dal bordo superiore fino alla punta sul fondo. Senza punto indietro.","Cuci tutti e quattro gli angoli. Ora l'esterno è una scatola, al rovescio: la teletta resta fuori."]},{title:"Cuci la fodera",text:"Prepara la fodera allo stesso modo, senza teletta, ma lascia un'apertura di 15 cm in una cucitura d'angolo. Da lì rivolterai il cestino.",details:["Solleva le pareti della croce della fodera, dritto contro dritto, e appunta i bordi che si incontrano.","Fai tre cuciture d'angolo a 0,5 cm dal bordo, dall'alto fino alla punta.","Cuci anche la quarta, ma lascia un'apertura di 15 cm. È così grande perché le pareti dell'esterno, con la teletta, sono rigide e serve spazio per farle passare.","Lascia la fodera al rovescio."]},{title:"Unisci esterno e fodera",text:"Rivolta l'esterno sul dritto e infilalo nella fodera al rovescio, dritto contro dritto. Cuci tutto intorno al bordo superiore, a 0,5 cm dal bordo.",details:["Rivolta l'esterno sul dritto.","Infilalo nella fodera, che resta al rovescio, così che siano dritto contro dritto. Allinea le cuciture d'angolo e i bordi superiori.","Cuci tutto intorno al bordo superiore, a 0,5 cm dal bordo."]},{title:"Rivoltalo sul dritto",text:"Rivolta il cestino sul dritto dall'apertura nella fodera, poi chiudi l'apertura a macchina.",details:["Tira fuori tutto il cestino attraverso l'apertura di 15 cm nella fodera.","Ripiega all'interno i bordi vivi dell'apertura e chiudila a macchina, vicino al bordo."]},{title:"Impuntura il bordo",text:"Spingi la fodera dentro il cestino e impuntura tutto intorno al bordo superiore, a 0,5 cm dal bordo.",details:["Spingi la fodera dentro il cestino, fino in fondo agli angoli.","Impuntura tutto intorno al bordo superiore, a 0,5 cm dal bordo. Il cestino è pronto: le decorazioni le scegli tu."]},{title:"Aggiungi le decorazioni",text:"Incolla un nastro intorno al bordo con la colla a caldo, con la giunzione su un lato, e un fiocco su ogni angolo. Va bene qualsiasi nastro e qualsiasi fiocco — o anche nessuno.",details:["Le decorazioni si incollano con la pistola per colla a caldo, non si cuciono.","Incolla un nastro tutto intorno al bordo superiore. Metti la giunzione sulla parte piatta di una parete, non su un angolo.","Incolla un fiocco su ciascuno dei quattro angoli. Nel video sono fatti prima con un nastro bianco, con una mezza perla rossa di plastica incollata al centro; vanno benissimo anche i fiocchi già pronti.","Qualsiasi nastro, di qualsiasi larghezza: pizzo per Natale, come nel video; un semplice nastro nero o uno arancione con le zucche per Halloween; oppure nessuna decorazione, per tutti i giorni. Nel video il cestino contiene i mandarini sulla tavola di Natale: tu usa il tuo per quello che vuoi."]}],legend:[{title:"Esterno",text:"cotone · un quadrato di 60 × 60 cm con un quadrato di 20 × 20 cm tagliato via da ogni angolo"},{title:"Teletta ×5",text:"rigida, termoadesiva · quadrati di 19 × 19 cm sul fondo e sulle pareti dell'esterno, a 0,5 cm dai bordi"},{title:"Fodera",text:"cotone · la stessa croce dell'esterno, senza teletta"},{title:"Nastro",text:"pizzo, o un nastro qualsiasi · incollato intorno al bordo con la colla a caldo, la giunzione su un lato"},{title:"Fiocchi ×4",text:"uno su ogni angolo, incollati, con una mezza perla rossa al centro"},{title:"Cuciture",text:"tutte a 0,5 cm · un'apertura di 15 cm in una cucitura d'angolo della fodera · impuntura a 0,5 cm dal bordo superiore"}]};export{i as default};
